'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{execFileSync}=require('node:child_process');
const {parse,walk}=require('../audits/audit-i18n-global.cjs');
const root=path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'],previous=execFileSync('git',['show','8f92528:plateau-construction-commandes.js'],{cwd:root,encoding:'utf8'});
function load(){const c={RP_I18N_GAME_ENABLED:true,RPPlateauI18n:{language:()=>c.locale||'fr'}};c.window=c;vm.createContext(c);for(const f of ['i18n/i18next.min.js','i18n/resources.js','i18n/naval-resources.js','i18n/toast-resources.js','i18n/construction-feedback-resources.js'])vm.runInContext(read(f),c);c.i18next.init({lng:'fr',fallbackLng:'fr',resources:c.RP_I18N_RESOURCES,initImmediate:false,interpolation:{escapeValue:false}});return c;}
function message(n){if(n?.type==='Literal'&&typeof n.value==='string')return n.value;if(n?.type==='Identifier')return {CHANTIER_SALAIRE_MINIMUM:'{{values.minimum}}',brut:'{{values.amount}}'}[n.name]??null;if(n?.type==='BinaryExpression'&&n.operator==='+'){const a=message(n.left),b=message(n.right);return a===null||b===null?null:a+b;}return null;}
test('20 clés : français exact, neuf langues, variables et unités conservées',()=>{
 const messages=new Set(),titles=new Set();walk(parse(previous),n=>{if(n.type==='CallExpression'&&n.callee.name==='showToast'){titles.add(n.arguments[0].value);const collect=node=>{const value=message(node);if(value!==null){messages.add(value);return;}if(node?.type==='ConditionalExpression'){collect(node.consequent);collect(node.alternate);}else if(node?.type==='LogicalExpression'&&node.operator==='||')collect(node.right);};collect(n.arguments[1]);}});
 const c=load(),fr=c.RP_I18N_RESOURCES.fr.translation.constructionFeedback;assert.equal(Object.keys(fr).length,20);assert.equal(Object.keys(fr).filter(k=>k.startsWith('title')).length,8);
 const vars=s=>(s.match(/\{\{[^}]+\}\}/g)||[]).sort();
 for(const [key,value]of Object.entries(fr))assert.ok((key.startsWith('title')?titles:messages).has(value),key);
 for(const lang of langs){const strings=c.RP_I18N_RESOURCES[lang].translation.constructionFeedback;assert.deepEqual(Object.keys(strings),Object.keys(fr));for(const [key,value]of Object.entries(strings)){assert.ok(value.trim());assert.deepEqual(vars(value),vars(fr[key]));if(fr[key].includes(' FR '))assert.ok(value.includes('FR'));if(lang!=='fr')assert.notEqual(value,fr[key]);}}
});
test('titres et repli français utilisent le service commun',()=>{
 const c=load();assert.equal(c.RPToastI18n.key('Commande non confirmée'),'naval.notConfirmed');for(const l of langs){assert.equal(c.RP_I18N_RESOURCES[l].translation.constructionFeedback.titleUnconfirmed,undefined);c.locale=l;c.i18next.changeLanguage(l);assert.equal(c.RPToastI18n.label('Commande acquise'),c.i18next.t('constructionFeedback.titleConfirmed'));assert.equal(c.RPToastI18n.label('Erreur'),c.i18next.t('toastTitles.error'));}
 const replacement=JSON.parse(JSON.stringify(c.RP_I18N_RESOURCES.de.translation));delete replacement.constructionFeedback.wageSaved;c.i18next.removeResourceBundle('de','translation');c.i18next.addResourceBundle('de','translation',replacement);c.locale='de';c.i18next.changeLanguage('de');assert.equal(c.i18next.t('constructionFeedback.wageSaved',{values:{amount:75}}),'Les ouvriers de votre chantier seront payés 75 FR de l’heure.');
});
function marker(n){const e=n?.expression?.type==='ChainExpression'?n.expression.expression:n?.expression;return n?.type==='ExpressionStatement'&&e?.type==='CallExpression'&&e.callee?.property?.name==='markToast'&&e.callee.object?.property?.name==='RPI18nPlateau'&&e.callee.object.object?.name==='window';}
function canonical(n,parent,field){if(!n||typeof n!=='object')return n;if(marker(n))return null;if(Array.isArray(n))return n.map(x=>canonical(x,parent,field)).filter(x=>x!==null);const out={};for(const [k,v]of Object.entries(n))if(!['start','end','loc','raw'].includes(k))out[k]=canonical(v,n,k);if(n.type==='BlockStatement'&&parent?.type==='IfStatement'&&['consequent','alternate'].includes(field)&&out.body.length===1&&out.body[0].type==='ExpressionStatement')return out.body[0];return out;}
test('dix seuls marqueurs de présentation : AST métier intégralement identique',()=>{
 const manifest='outils/audits/I18N-RETOURS-CHANTIERS-871-preuve.json';let source=read('plateau-construction-commandes.js');if(fs.existsSync(path.join(root,manifest))){const proof=JSON.parse(read(manifest));source=execFileSync('git',['show',proof.codeCommit+':plateau-construction-commandes.js'],{cwd:root,encoding:'utf8'});}
 assert.deepEqual(canonical(parse(source)),canonical(parse(previous)));
 const baselineKeys=new Set(),currentKeys=new Set();let frozenCount=0;walk(parse(source),n=>{if(marker(n)){frozenCount++;const e=n.expression.type==='ChainExpression'?n.expression.expression:n.expression;if(e.arguments[0].type==='Literal')baselineKeys.add(e.arguments[0].value);}});assert.equal(frozenCount,10);walk(parse(read('plateau-construction-commandes.js')),n=>{if(marker(n)){const e=n.expression.type==='ChainExpression'?n.expression.expression:n.expression;if(e.arguments[0].type==='Literal')currentKeys.add(e.arguments[0].value);}});for(const key of baselineKeys)assert.ok(currentKeys.has(key),key);
 assert.ok(read('plateau.html').indexOf('i18n/toast-resources.js')<read('plateau.html').indexOf('i18n/construction-feedback-resources.js'));
 const base=execFileSync('git',['merge-base','HEAD','origin/main'],{cwd:root,encoding:'utf8'}).trim();assert.equal(execFileSync('git',['diff','--name-only',base,'--','api','migrations','supabase','data.js','plateau-construction.js'],{cwd:root,encoding:'utf8'}),'');
});
